// Auditoria de Data Exposure (13/08): a RPC calcula 'segmento' e 'ticket_medio'
// (classificacao interna/metrica financeira) e 'dias_desde_ultima_compra'/
// 'ciclo_dias' (reservados pra uma futura feature de previsao de recompra,
// ainda sem instrucao de uso no agente). Nenhum desses campos e referenciado
// por nenhuma regra do system prompt hoje -- pelo teste "o agente precisa
// disso pra funcionar?", a resposta e nao, entao nao devem entrar no
// contexto do LLM. RPC continua calculando tudo (fica disponivel pra uso
// futuro), so nao trafega por aqui.
const row = $input.first()?.json?.contexto || { encontrado: false };
if (!row.encontrado) return [{ json: row }];

const produtosRecorrentes = (row.produtos_recorrentes || []).map(p => ({
  produto_nome: p.produto_nome,
  especie: p.especie,
}));

return [{ json: {
  encontrado: true,
  nome: row.nome,
  saldo_petcash: row.saldo_petcash,
  pets: row.pets,
  ultimo_pedido: row.ultimo_pedido,
  produtos_recorrentes: produtosRecorrentes,
  ambiguidade_multiplas_especies: row.ambiguidade_multiplas_especies,
} }];
